{
  "hypotheses": [
    {
      "text": "Apple submits multiple filings (original 10-Qs, 10-K, and subsequent amendments/restatements) for FY2022, each filing contains a revenue fact, resulting in duplicate rows for the same fiscal period.",
      "how_to_test": "SELECT cik, fiscal_year, fiscal_period, form_type, COUNT(*) AS row_cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik='320193' AND fiscal_year=2022 GROUP BY cik, fiscal_year, fiscal_period, form_type ORDER BY row_cnt DESC;"
    },
    {
      "text": "Two different XBRL concepts are used for revenue: 'Revenues' and 'RevenueFromContractWithCustomerExcludingAssessedTax'. Both concepts are reported in each filing, effectively doubling the number of rows per filing.",
      "how_to_test": "SELECT concept, COUNT(*) AS cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik='320193' AND fiscal_year=2022 GROUP BY concept;"
    },
    {
      "text": "Apple reports revenue for each quarterly filing (10-Q) and the annual filing (10-K) for FY2022, giving four quarterly rows plus one annual row per concept, and when combined with amendments yields the observed count.",
      "how_to_test": "SELECT fiscal_period, form_type, COUNT(*) AS cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik='320193' AND fiscal_year=2022 GROUP BY fiscal_period, form_type ORDER BY fiscal_period, form_type;"
    },
    {
      "text": "Revenue facts are tagged with dimensional information (e.g., geographic region or product segment) in the XBRL instance, causing a separate row for each dimension combination within the same filing; this reflects Apple's multi‑segment business rather than a data error.",
      "how_to_test": "SELECT cik, fiscal_year, fiscal_period, accession_number, COUNT(*) AS dim_cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik='320193' AND fiscal_year=2022 GROUP BY cik, fiscal_year, fiscal_period, accession_number HAVING COUNT(*) > 1;"
    }
  ]
}
